import { useState } from "react";
import { createRoot } from "react-dom/client";

import Queue from "./components/Queue";
import ThreadPanel from "./components/ThreadPanel";
import fixtures from "./fixtures.json";
import { BUNDLE_LABELS, threadFor, type Facility, type PatientRow } from "./data";
import "./theme.css";

/** Development harness. Not part of the remote, and deliberately plain: the
 *  real chrome is care_fe's, so anything chrome-like here would be a lie about
 *  what the plugin looks like in place.
 *
 *  fixtures.json is GENERATED by scripts/gen-fixtures.py from the real
 *  derivation in care_phc/thread.py, so the actions shown are what the backend
 *  would return, not a second implementation of the rules in TypeScript.
 *  Regenerate with `npm run fixtures`. */
const facility = fixtures as unknown as Facility;

function App() {
  const [bundle, setBundle] = useState("mo");
  const [open, setOpen] = useState<PatientRow | null>(null);
  const [tab, setTab] = useState("all");
  const [dark, setDark] = useState(false);
  const [picked, setPicked] = useState<string | null>(null);

  document.documentElement.dataset.theme = dark ? "dark" : "light";

  return (
    <div className="phc" style={{ maxWidth: 1080, margin: "0 auto", padding: 24 }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 4 }}>
        <h1 style={{ font: "600 17px Inter, system-ui", margin: 0, letterSpacing: "-.01em" }}>
          care_phc_fe harness
        </h1>
        <span style={{ color: "var(--ink-3)", fontSize: 12.5 }}>
          the two surfaces this plugin adds to care_fe
        </span>
        <button
          onClick={() => setDark(!dark)}
          className="badge b-mute"
          style={{ marginLeft: "auto", cursor: "pointer", padding: "5px 11px" }}
        >
          {dark ? "Light" : "Dark"}
        </button>
      </div>
      <p style={{ color: "var(--ink-3)", fontSize: 12.5, margin: "0 0 18px", lineHeight: 1.6 }}>
        In place, both of these sit inside CARE's own sidebar and pages. The patient
        directory, search and command palette are CARE's and are not rebuilt here.
      </p>

      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 16 }}>
        {Object.keys(facility.bundles).map((b) => (
          <button
            key={b}
            onClick={() => setBundle(b)}
            className="badge b-mute"
            style={{
              cursor: "pointer", padding: "6px 12px",
              background: b === bundle ? "var(--ink)" : undefined,
              borderColor: b === bundle ? "var(--ink)" : undefined,
              color: b === bundle ? "var(--surface)" : undefined,
            }}
          >
            {BUNDLE_LABELS[b] ?? b}
          </button>
        ))}
      </div>

      <div className="eyebrow" style={{ marginBottom: 10 }}>Station queue · plugin route</div>
      <Queue
        patients={facility.patients}
        tab={tab}
        onTab={setTab}
        onOpen={(p) => {
          setOpen(p);
          setPicked(null);
        }}
      />

      <div className="eyebrow" style={{ margin: "26px 0 10px" }}>Patient thread · encounter tab</div>
      {open ? (
        <>
          <ThreadPanel
            thread={threadFor(open, bundle, facility)}
            bundleLabel={BUNDLE_LABELS[bundle] ?? bundle}
            onAction={(a) => setPicked(a.tool)}
          />
          {picked && (
            <p style={{ color: "var(--ink-3)", fontSize: 12.5, marginTop: 14 }}>
              Would call <code>{picked}</code> on the guard. It opens CARE's questionnaire
              for this operation, which is not wired yet.
            </p>
          )}
        </>
      ) : (
        <div className="card" style={{ padding: 34, textAlign: "center", color: "var(--ink-3)", fontSize: 12.5 }}>
          Pick someone from the queue above.
        </div>
      )}
    </div>
  );
}

createRoot(document.getElementById("root")!).render(<App />);
